//! A FITS-WCS write gives the LONPOLE and LATPOLE C gives (fitschan.c
//! `SkyPole`): a projection wcsmap.c `IsZenithal` counts as zenithal writes
//! only the pole its WcsMap was given, and any other has the pole worked out
//! from its Mappings. HPX and CAR are not zenithal, and neither are SIN with
//! a slant or AZP with a tilt.
//!
//! `sky_pole_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_pole_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "sky_pole_oracle/cases.rs"]
mod cases;

use ast_core::channel::Channel;

/// Cases C refuses that the port reads. With an explicit LONPOLE that cannot
/// hold for the reference point, C's `WcsNative` reports the native-to-
/// celestial conversion ill-conditioned (AST__BDFTS, fitschan.c:38553); the
/// port's reader returns no rotation from `wcs_nat_pole` and carries on.
/// That is a FitsChan read gap, recorded in `docs/audits/mapping-c-parity.md`
/// beside WC-1, not a SkyPole one.
const NOT_REFUSED: &[(&str, &str)] = &[
    (
        "hpx_pole",
        "the port reads a LONPOLE C finds ill-conditioned",
    ),
    (
        "car_pole",
        "the port reads a LONPOLE C finds ill-conditioned",
    ),
];
use ast_core::fitschan::{Encoding, FitsChan};

fn header(proj: &str, extra: &str) -> String {
    let mut h = String::new();
    for card in [
        "NAXIS   = 2".to_string(),
        "NAXIS1  = 100".to_string(),
        "NAXIS2  = 100".to_string(),
        "CRPIX1  = 50.0".to_string(),
        "CRPIX2  = 50.0".to_string(),
        "CRVAL1  = 30.0".to_string(),
        "CRVAL2  = 40.0".to_string(),
        "CDELT1  = -0.01".to_string(),
        "CDELT2  = 0.01".to_string(),
        format!("CTYPE1  = 'RA---{proj}'"),
        format!("CTYPE2  = 'DEC--{proj}'"),
        "RADESYS = 'ICRS'".to_string(),
    ] {
        h.push_str(&card);
        h.push('\n');
    }
    h.push_str(extra);
    h
}

/// The LONPOLE and LATPOLE written for a case, or `None` when the port does
/// not read and write it.
fn written(proj: &str, extra: &str) -> Option<(Option<f64>, Option<f64>)> {
    let mut fc = FitsChan::from_header(&header(proj, extra)).ok()?;
    fc.set_encoding(Encoding::FitsWcs);
    let obj = fc.read().ok()??;
    let mut out = FitsChan::new();
    out.set_encoding(Encoding::FitsWcs);
    out.write(&obj).ok()?;
    Some((out.get_fits_f("LONPOLE"), out.get_fits_f("LATPOLE")))
}

#[test]
fn sky_pole_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, proj, extra, lonpole, latpole, ok) in cases::CASES {
        if NOT_REFUSED.iter().any(|(n, _)| *n == name) {
            continue;
        }
        let written = written(proj, extra);
        let got = match written {
            Some((lon, lat)) if ok => lon == lonpole && lat == latpole,
            None => !ok,
            Some(_) => false,
        };
        if !got {
            failures.push(format!(
                "{name}: {written:?}, C gives LONPOLE {lonpole:?} LATPOLE {latpole:?} (ok {ok})"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Every case in `NOT_REFUSED` is one C refuses and the port still reads; one
/// the port starts refusing has to leave the list.
#[test]
fn not_refused_cases_are_still_read() {
    for (name, reason) in NOT_REFUSED {
        let &(_, proj, extra, _, _, ok) =
            cases::CASES.iter().find(|c| c.0 == *name).expect("a case");
        assert!(
            !ok,
            "{name}: C reads it, so it does not belong in NOT_REFUSED"
        );
        assert!(
            written(proj, extra).is_some(),
            "{name} is now refused, as C refuses it; remove it from NOT_REFUSED ({reason})"
        );
    }
}
